def schedule(pod, nodes):
    """Pick a node for `pod` by filtering, then scoring with LeastAllocated.

    pod:   {"cpu": int, "mem": int, "tolerations": set of str (optional)}
    nodes: {name: {"cpu": int, "mem": int, "used_cpu": int, "used_mem": int, "taints": set of str}}
    Return the chosen node's name, or None if no node passes the filter.
    """
    candidates = []
    for name in sorted(nodes):
        node = nodes[name]
        # filter: enough unreserved CPU and memory, and every taint tolerated
        candidates.append(name)
    # score: 100 * ((C - c)/C + (M - m)/M) / 2, where c and m include the new pod;
    # return the highest-scoring candidate, ties going to the alphabetically first name
    return candidates[0] if candidates else None

exercises.tests:
def _n(cpu, mem, used_cpu=0, used_mem=0, taints=()):
    return {"cpu": cpu, "mem": mem, "used_cpu": used_cpu, "used_mem": used_mem, "taints": set(taints)}

web = {"cpu": 500, "mem": 1024}
nodes = {"a": _n(4000, 8192, 3000, 4096), "b": _n(4000, 8192, 1000, 2048), "c": _n(4000, 8192, 2000, 2048)}
assert schedule(web, nodes) == "b", "the emptiest node after placement wins"

nodes = {"a": _n(4000, 8192, 3800, 0), "b": _n(4000, 8192, 0, 7900), "c": _n(4000, 8192, 3500, 7168)}
assert schedule(web, nodes) == "c", "a and b fail the filter (CPU on a, memory on b); c fits exactly"

nodes = {"gpu": _n(16000, 65536, taints={"gpu"}), "small": _n(2000, 4096, 1000, 1024)}
assert schedule(web, nodes) == "small", "a pod without the toleration must not land on a tainted node"
assert schedule({"cpu": 500, "mem": 1024, "tolerations": {"gpu"}}, nodes) == "gpu", "with the toleration, the emptier GPU node wins"

assert schedule({"cpu": 8000, "mem": 1024}, nodes) is None, "nothing fits: return None"
assert schedule(web, {"x": _n(4000, 8192), "w": _n(4000, 8192)}) == "w", "ties go to the alphabetically first name"
assert schedule(web, {}) is None

exercises.reference:
def schedule(pod, nodes):
    tolerations = pod.get("tolerations", set())
    best, best_score = None, None
    for name in sorted(nodes):
        n = nodes[name]
        c, m = n["used_cpu"] + pod["cpu"], n["used_mem"] + pod["mem"]
        if c > n["cpu"] or m > n["mem"] or not n["taints"] <= tolerations:
            continue
        s = 100 * ((n["cpu"] - c) / n["cpu"] + (n["mem"] - m) / n["mem"]) / 2
        if best_score is None or s > best_score:
            best, best_score = name, s
    return best
